 useEffect(()=>{const q=new URLSearchParams(location.search);const authFailure=authRedirectError(location.search,location.hash);if(authFailure){setError(authFailure);setPublicPage('auth');setAuthMode('login');for(const key of ['auth_error','error','error_code','error_description','code'])q.delete(key);history.replaceState({},'',location.pathname+(q.size?'?'+q.toString():''));}if(q.get('auth')==='verified'){message('You are signed in. Welcome to Timecard.');history.replaceState({},'','/');}if(q.get('billing')&&q.get('org')){setOrg(q.get('org')!);setPage('Billing');}if(q.get('invite')){setInvite(q.get('invite')!);setPublicPage('auth');setAuthMode('signup');}if(q.get('reset')){setReset(q.get('reset')!);setPublicPage('auth');setAuthMode('reset');}if(q.get('verify')){api('auth/verify',{token:q.get('verify')}).then(()=>{message('Email verified. Welcome to Timecard.');history.replaceState({},'','/');refresh();}).catch(e=>setError(e.message));}setOnline(navigator.onLine);const update=()=>setOnline(navigator.onLine);window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update);};},[]);
 useEffect(()=>{if(!state?.user)return;try{setQueue(JSON.parse(localStorage.getItem('timecard-queue-'+state.user.id)||'[]'));}catch{setQueue([]);}},[state?.user?.id]);
