 {page==='Billing'&&<><div className="page-heading"><div><h1>A plan for your people.</h1><p>Choose the space your team needs to do good work.</p></div></div><Pricing current={o.plan} upgrade={async()=>{try{const r=await api('billing/checkout',{});location.assign(r.url);}catch(e){setError((e as Error).message);}}} sales={contactSales}/></>}
 {page==='Profile'&&<><div className="page-heading"><div><h1>Your workday, your space.</h1><p>A simple start. And a little peace of mind.</p></div><button className="button" onClick={signout}><LogOut size={17}/>Sign out</button></div><div className="profile-grid"><section className="panel profile-panel"><span className="avatar profile-avatar">{initials(user.name)}</span><h2>{user.name}</h2><p>{user.email}</p><Badge status="verified"/><div className="profile-facts"><span>Workspace<strong>{o.name}</strong></span><span>Your role<strong className="capitalize">{state.membership.role}</strong></span><span>Retention<strong>{o.retention} days</strong></span></div></section><section className="panel consent-panel"><ShieldCheck size={28}/><h2>Your trust comes first.</h2><p>To mark attendance, we compare a mathematical face template and check your location against your work area. Location is collected only when you check in or out, never continuously.</p><p>Face verification is processed by AWS Rekognition. Timecard stores an encrypted face identifier, not your photo. Attendance is retained for {o.retention} days. Your workspace managers can see attendance verification details and recorded coordinates.</p><p>You can delete your biometric data below. If you prefer not to consent, ask your manager about manual attendance approval.</p>{!state.membership.consent?<Form submit="Accept and continue" onSubmit={async d=>{if(!d.accept)throw Error('Please select the consent checkbox.');await act('consent',{accept:true},'Thank you. You can now enroll your face.');}}><label className="checkbox"><input name="accept" type="checkbox" required/>I have read this notice and consent to biometric and location processing for attendance.</label></Form>:<div className="verified"><CheckCircle2 size={18}/>Consent accepted on {new Date(state.membership.consent).toLocaleDateString()}</div>}<div className="enrollment"><ScanFace size={30}/><div><h3>{state.faceEnrolled?'A familiar face.':'Let’s get to know you.'}</h3><p>{state.faceEnrolled?'Your face is enrolled and ready for check-in.':'A guided camera check helps keep your attendance yours.'}</p></div>{state.faceEnrolled?<button className="button danger-text" onClick={()=>setModal({title:'Delete your face template?',body:<Form danger submit="Delete biometric data" onSubmit={async()=>{await act('face/delete',{},'Your biometric data has been deleted.');setModal(null);}}><p>Your face template will be deleted from AWS and Timecard. You will need to enroll again for face check-in.</p></Form>})}><Trash2 size={16}/>Delete</button>:<button className="button primary" disabled={!state.membership.consent} onClick={()=>capture('enroll')}>Enroll face <ArrowRight size={16}/></button>}</div>{!state.faceConfigured&&<p className="note">Face verification setup is pending. Your manager can finish provider configuration.</p>}</section></div>{isManager&&<div className="section-gap"><ClockCard current={open} record={todayRecord} clock={clock} capture={()=>capture('verify')} pause={()=>act('break',{action:open?.break_start?'end':'start'}).catch(e=>setError(e.message))}/></div>}<div className="section-gap"><button className="text-button" onClick={manual}>Request manual attendance approval <ArrowUpRight size={16}/></button></div>{state.manualRequests.filter((r:Row)=>r.user_id===user.id).length>0&&<section className="panel section-gap"><h2>Your attendance requests</h2>{state.manualRequests.filter((r:Row)=>r.user_id===user.id).map((r:Row)=><div className="request-line" key={r.id}><span className="grow">Check {r.action} · {new Date(r.created).toLocaleDateString()}</span><Badge status={r.status}/></div>)}</section>}</>}
 {isManager&&['Dashboard','Team Attendance'].includes(page)&&state.manualRequests.some((r:Row)=>r.status==='pending')&&<section className="panel section-gap"><div className="section-head"><div><h2>A helping hand needed.</h2><p>Attendance requests waiting for manual review.</p></div></div>{state.manualRequests.filter((r:Row)=>r.status==='pending').map((r:Row)=><div className="request-line" key={r.id}><span className="avatar soft">{initials(r.name)}</span><div className="grow"><strong>{r.name} · Check {r.action}</strong><small>{r.reason}</small></div><button className="button compact" onClick={()=>decideManual(r,'declined')}>Decline</button><button className="button primary compact" onClick={()=>decideManual(r,'approved')}>Review</button></div>)}</section>}
 {page==='Profile'&&<AccountControls state={state} api={api} refresh={refresh} signedOut={signout}/>}
